style.css:
body {
    background-image: url('https://media.discordapp.net/attachments/1340917113640190016/1341917804722651166/Real_look_at_Ellis_hes_getting_prizes.jpg?ex=67b7bdd8&is=67b66c58&hm=2bfe728eea1352e630cb0a1c33e3c8c01a93199cf4c1b69de3037ddf052aa6d4&=&format=webp&width=948&height=592'); 
    background-size: cover;
    background-position: center; 
    background-repeat: no-repeat; 
    background-attachment: fixed; 
    color: #ffffff; 
    font-family: 'Arial', sans-serif; 
}


body::before {
    content: '';
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.5);
    z-index: -1;
}
